#!/usr/bin/env python3
"""Atomic HTTP/3 -> HTTP/1.1 translation bridge (offline synthetic fixtures).

Reads one JSON scenario on stdin, writes one JSON audit ledger on stdout.
Field strings and ledger strings denote Latin-1 octets (U+0000..U+00FF).
"""

import ipaddress
import json
import re
import sys

# --------------------------------------------------------------------------
# deployment policy tables
# --------------------------------------------------------------------------

METHODS = frozenset((b"GET", b"HEAD", b"POST", b"PUT", b"PATCH", b"DELETE",
                     b"OPTIONS"))
SCHEMES = frozenset((b"http", b"https"))
DEFAULT_PORT = {"http": 80, "https": 443}

# initial regular fields that may never appear
PROHIBITED = frozenset((
    b"connection", b"proxy-connection", b"keep-alive", b"transfer-encoding",
    b"upgrade", b"http2-settings", b"trailer"))

# initial regular fields that may repeat as separate lines
REPEATABLE = frozenset((
    b"accept", b"accept-encoding", b"cache-control", b"if-match",
    b"if-none-match", b"pragma", b"vary"))

PSEUDO = frozenset((b":method", b":scheme", b":authority", b":path"))

MAX_SECTION_SIZE = 8192
MAX_CONTENT = 65536

# --------------------------------------------------------------------------
# octet-shaped grammar
# --------------------------------------------------------------------------

NAME_RE = re.compile(rb"[a-z0-9!#$%&'*+\-.^_`|~]+\Z")
VALUE_RE = re.compile(rb"[\x21-\x7e\x80-\xff][\t\x20\x21-\x7e\x80-\xff]*"
                      rb"[\x21-\x7e\x80-\xff]?\Z")
PATH_RE = re.compile(rb"/(?:[a-zA-Z0-9\-._~!$&'()*+,;=:@/?]|%[0-9a-fA-F]{2})*\Z")
DNS_LABEL_RE = re.compile(r"[0-9a-zA-Z](?:[0-9a-zA-Z-]{0,61}[0-9a-zA-Z])?\Z")
PORT_RE = re.compile(r"[0-9]{1,5}\Z")
CL_MEMBER_RE = re.compile(rb"[0-9]+\Z")
HEX_PAIR_RE = re.compile(rb"[0-9a-fA-F]{2}")

ANCHOR = re.compile(r"\A(?:x)")
_Z = re.compile(r"\Z")


def name_ok(name):
    """Regular field name: nonempty, lowercase letters/digits/punctuation."""
    if not name:
        return False
    return NAME_RE.match(name) is not None


def value_ok(value):
    """Empty, or visible-octet edges with SP/HTAB allowed only inside."""
    if not value:
        return True
    return VALUE_RE.match(value) is not None


def path_ok(path, method):
    if path == b"*":
        return method == b"OPTIONS"
    if not path.startswith(b"/") or path[1:2] == b"/":
        return False
    return PATH_RE.match(path) is not None


def digits_norm(member):
    stripped = member.lstrip(b"0")
    return stripped if stripped else b"0"


def content_length_ok(lines):
    """Return True when every comma member denotes the same integer."""
    wanted = None
    for line in lines:
        for member in line.split(b","):
            member = member.strip(b" \t")
            if not member or CL_MEMBER_RE.match(member) is None:
                return None
            norm = digits_norm(member)
            if wanted is None:
                wanted = norm
            elif norm != wanted:
                return None
    return wanted


# --------------------------------------------------------------------------
# authority canonicalisation
# --------------------------------------------------------------------------

def port_ok(text):
    if PORT_RE.match(text) is None:
        return None
    value = int(text)
    if value < 1 or value > 65535:
        return None
    return value


def dns_host_ok(text):
    """Return lowercased DNS name, or None."""
    if len(text) < 1 or len(text) > 253:
        return None
    labels = text.split(".")
    if len(labels) == 4:
        quad = True
        for label in labels:
            if not label:
                quad = False
                break
            for ch in label:
                if ch < "0" or ch > "9":
                    quad = False
                    break
            if not quad:
                break
        if quad:
            for label in labels:
                if len(label) > 1 and label[0] == "0":
                    return None
                if int(label) > 255:
                    return None
            return ".".join(str(int(label)) for label in labels)
    for label in labels:
        if not label or not label.isascii():
            return None
        if DNS_LABEL_RE.match(label) is None:
            return None
    return text.lower()


def authority_canonical(raw, scheme):
    """Canonical authority string for Latin-1 octets, or None."""
    try:
        text = raw.decode("latin-1")
    except UnicodeDecodeError:
        return None
    port = None
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        inner = text[1:end]
        rest = text[end + 1:]
        if "%" in inner or "%" in rest:
            return None
        if rest:
            if not rest.startswith(":"):
                return None
            port = port_ok(rest[1:])
            if port is None:
                return None
        if not inner or not inner.isascii():
            return None
        try:
            host = "[" + ipaddress.IPv6Address(inner).compressed + "]"
        except ValueError:
            return None
    else:
        cut = text.find(":")
        if cut >= 0:
            port = port_ok(text[cut + 1:])
            if port is None:
                return None
            hostpart = text[:cut]
        else:
            hostpart = text
        if not hostpart or not hostpart.isascii():
            return None
        host = dns_host_ok(hostpart)
        if host is None:
            return None
    if port is not None and port != DEFAULT_PORT[scheme]:
        host = host + ":" + str(port)
    return host


# --------------------------------------------------------------------------
# per-section parsing
# --------------------------------------------------------------------------

def section_size(pairs):
    total = 0
    for name, value in pairs:
        total += len(name) + len(value) + 32
    return total


def parse_initial(pairs):
    """Validate initial HEADERS; return summary dict or None."""
    if section_size(pairs) > MAX_SECTION_SIZE:
        return None
    seen_pseudo = set()
    method = scheme = path = authority = host = None
    regular = []
    past_regular = False
    for name, value in pairs:
        if name[:1] == b":":
            if past_regular or name not in PSEUDO or name in seen_pseudo:
                return None
            seen_pseudo.add(name)
            if not value_ok(value):
                return None
            if name == b":method":
                if method is not None:
                    return None
                method = value
            elif name == b":scheme":
                if scheme is not None:
                    return None
                scheme = value
            elif name == b":path":
                if path is not None:
                    return None
                path = value
            else:
                if authority is not None:
                    return None
                authority = value
            continue
        if not name_ok(name) or not value_ok(value):
            return None
        past_regular = True
        if name == b"host":
            if host is not None:
                return None
            host = value
        else:
            regular.append((name, value))

    if method is None or scheme is None or path is None:
        return None
    if method not in METHODS or scheme not in SCHEMES:
        return None
    if not path_ok(path, method):
        return None

    if authority is None and host is None:
        return None
    if authority is not None:
        if not authority:
            return None
        if host is not None and host != authority:
            return None
    elif not host:
        return None
    chosen = authority if authority is not None else host

    scheme_text = scheme.decode("ascii")
    canon = authority_canonical(chosen, scheme_text)
    if canon is None:
        return None

    counts = {}
    for name, _value in regular:
        counts[name] = counts.get(name, 0) + 1
    for name in counts:
        if name in PROHIBITED:
            return None

    te_lines = [value for name, value in regular if name == b"te"]
    if len(te_lines) > 1 or (te_lines and te_lines[0] != b"trailers"):
        return None

    cl_lines = [value for name, value in regular if name == b"content-length"]
    cl = None
    if cl_lines:
        cl = content_length_ok(cl_lines)
        if cl is None:
            return None

    for name, count in counts.items():
        if count == 1:
            continue
        if name in REPEATABLE or name in (b"cookie", b"content-length"):
            continue
        if name.startswith(b"x-list-") and len(name) > 7:
            continue
        return None

    cookie_values = [value for name, value in regular if name == b"cookie"]
    return {
        "method": method,
        "scheme": scheme_text,
        "path": path,
        "canon": canon,
        "regular": regular,
        "cookie_values": cookie_values,
        "cl": cl,
    }


def parse_trailers(pairs):
    if section_size(pairs) > MAX_SECTION_SIZE:
        return None
    for name, value in pairs:
        if not name_ok(name) or not value_ok(value):
            return None
        if not name.startswith(b"x-audit-") or len(name) <= 8:
            return None
    return True


# --------------------------------------------------------------------------
# serialization
# --------------------------------------------------------------------------

def serialize(summary, content, trailers):
    out = bytearray()
    out += summary["method"]
    out += b" "
    out += summary["path"]
    out += b" HTTP/1.1\r\nhost: "
    out += summary["canon"].encode("latin-1")
    out += b"\r\n"

    cookie_values = summary["cookie_values"]
    joined = b"; ".join(cookie_values) if cookie_values else b""
    emitted_cookie = False
    for name, value in summary["regular"]:
        if name == b"content-length" or name == b"te":
            continue
        if name == b"cookie":
            if not emitted_cookie:
                emitted_cookie = True
                out += b"cookie: "
                out += joined
                out += b"\r\n"
            continue
        out += name
        out += b": "
        out += value
        out += b"\r\n"

    if trailers is None:
        out += b"content-length: "
        out += str(len(content)).encode("ascii")
        out += b"\r\n\r\n"
        out += content
    else:
        out += b"transfer-encoding: chunked\r\n"
        if trailers:
            announced = []
            seen = set()
            for name, _value in trailers:
                if name not in seen:
                    seen.add(name)
                    announced.append(name)
            out += b"trailer: "
            out += b", ".join(announced)
            out += b"\r\n"
        out += b"\r\n"
        if content:
            out += format(len(content), "x").encode("ascii")
            out += b"\r\n"
            out += content
            out += b"\r\n"
        out += b"0\r\n"
        for name, value in trailers:
            out += name
            out += b": "
            out += value
            out += b"\r\n"
        out += b"\r\n"
    return bytes(out)


# --------------------------------------------------------------------------
# stream machinery
# --------------------------------------------------------------------------

def blank_record(sid, status):
    return {"sid": sid, "status": status, "commit_at": None, "origin": None,
            "offset": None, "length": 0, "cache_key": None}


def octets(text):
    """Latin-1 octets for a JSON field string, or None when out of range."""
    if not isinstance(text, str):
        return None
    try:
        return text.encode("latin-1")
    except UnicodeEncodeError:
        return None


def build_request(state, routes):
    summary = parse_initial(state["initial"])
    if summary is None:
        return None
    content = bytes(state["content"])
    if len(content) > MAX_CONTENT:
        return None
    cl = summary["cl"]
    if cl is not None and cl != digits_norm(b"%d" % len(content)):
        return None
    if state["trailing"] is not None:
        if parse_trailers(state["trailing"]) is None:
            return None
    route_key = summary["scheme"] + "://" + summary["canon"]
    origin = routes.get(route_key)
    if origin is None:
        return None
    cache_key = [summary["method"].decode("ascii"), summary["scheme"],
                 summary["canon"], summary["path"].decode("latin-1")]
    return origin, serialize(summary, content, state["trailing"]), cache_key


def finalize(sid, state, commit_at, routes, pipelines):
    record = blank_record(sid, "rejected")
    if state["bad"] or state["initial"] is None:
        return record
    built = build_request(state, routes)
    if built is None:
        return record
    origin, raw, cache_key = built
    pipeline = pipelines[origin]
    record["status"] = "forwarded"
    record["commit_at"] = commit_at
    record["origin"] = origin
    record["offset"] = len(pipeline)
    record["length"] = len(raw)
    record["cache_key"] = cache_key
    pipeline += raw
    return record


def run(scenario):
    routes = scenario.get("routes") or {}
    events = scenario.get("events") or []

    pipelines = {}
    for label in routes.values():
        if label not in pipelines:
            pipelines[label] = bytearray()

    streams = {}
    results = {}

    for index, event in enumerate(events):
        sid = event["sid"]
        state = streams.get(sid)
        if state is None:
            state = {"initial": None, "trailing": None, "content": bytearray(),
                     "bad": False, "done": False}
            streams[sid] = state
        if state["done"]:
            continue

        kind = event["type"]
        if kind == "unknown":
            continue
        if kind == "headers":
            pairs = []
            healthy = True
            for pair in event["fields"]:
                name = octets(pair[0])
                value = octets(pair[1])
                if name is None or value is None:
                    healthy = False
                    name = b"" if name is None else name
                    value = b"" if value is None else value
                pairs.append((name, value))
            if not healthy:
                state["bad"] = True
            if state["initial"] is None:
                state["initial"] = pairs
            elif state["trailing"] is None:
                state["trailing"] = pairs
            else:
                state["bad"] = True
        elif kind == "data":
            blob = event["hex"]
            if isinstance(blob, str):
                try:
                    state["content"] += bytes.fromhex(blob)
                except ValueError:
                    state["bad"] = True
            else:
                state["bad"] = True
            if state["initial"] is None or state["trailing"] is not None:
                state["bad"] = True
        elif kind == "reset":
            state["done"] = True
            results[sid] = blank_record(sid, "cancelled")
        elif kind == "fin":
            state["done"] = True
            results[sid] = finalize(sid, state, index, routes, pipelines)

    for sid, state in streams.items():
        if not state["done"]:
            results[sid] = blank_record(sid, "incomplete")

    return {
        "streams": [results[sid] for sid in sorted(results)],
        "origins": {label: bytes(pipe).hex() for label, pipe in pipelines.items()},
    }


def main():
    data = sys.stdin.buffer.read()
    scenario = json.loads(data.decode("utf-8"))
    result = run(scenario)
    json.dump(result, sys.stdout, ensure_ascii=True, separators=(",", ":"))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
