    """Independent H1 parse; returns list of request dicts."""
    out = []
    pos = 0
    while pos < len(raw):
        start = pos
        def readline(p):
            e = raw.index(b'\r\n', p)
            return raw[p:e], e + 2
        reqline, pos = readline(pos)
        fields = []
        while True:
            line, pos = readline(pos)
            if not line:
                break
            n, v = line.split(b': ', 1)
            fields.append((n, v))
        d = dict(fields)
        body = b''
        trailers = []
        if d.get(b'transfer-encoding') == b'chunked':
            while True:
                sz, pos = readline(pos)
                n = int(sz, 16)
                if n == 0:
                    break
                body += raw[pos:pos+n]
                assert raw[pos+n:pos+n+2] == b'\r\n', 'bad chunk terminator'
                pos += n + 2
            while True:
                line, pos = readline(pos)
                if not line:
                    break
                trailers.append(line)
        else:
            n = int(d[b'content-length'])
            body = raw[pos:pos+n]
            assert len(body) == n
            pos += n
        out.append({'offset': start, 'length': pos - start, 'request': reqline,
                    'fields': fields, 'body': body, 'trailers': trailers})
    return out

